#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int MAXN = 210;
const int MAXM = 1000007;

int n, T;
char s1[15][15], s2[15][15];
int id[15][15], cnt;
int source, sink;
int xz, yz;
int directions[4][2] = { {0,1}, {0,-1}, {1,0}, {-1,0} };

bool check_inside(int x, int y) {
    return x >= 0 && y >= 0 && x < n && y < n && s1[x][y] >= '0' && s1[x][y] <= '9';
}

int vv[MAXM], cap[MAXM], nxt[MAXM], head[MAXN], edge_idx = 0;
int parent[MAXN], visited[MAXN];

void add_edge(int u, int v, int c) {
    vv[edge_idx] = v; cap[edge_idx] = c; nxt[edge_idx] = head[u]; head[u] = edge_idx++;
    vv[edge_idx] = u; cap[edge_idx] = 0; nxt[edge_idx] = head[v]; head[v] = edge_idx++;
}

int run_max_flow() {
    int total = 0;
    while (true) {
        memset(parent, -1, sizeof(parent));
        memset(visited, 0, sizeof(visited));
        queue<int> q;
        q.push(source);
        visited[source] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int i = head[u]; i != -1; i = nxt[i]) {
                int v = vv[i];
                if (cap[i] > 0 && !visited[v]) {
                    visited[v] = 1;
                    parent[v] = i;
                    if (v == sink) goto augment;
                    q.push(v);
                }
            }
        }
        break;
        augment:
        int flow = 1e9;
        for (int v = sink; v != source; v = vv[parent[v] ^ 1]) {
            flow = min(flow, cap[parent[v]]);
        }
        for (int v = sink; v != source; v = vv[parent[v] ^ 1]) {
            cap[parent[v]] -= flow;
            cap[parent[v] ^ 1] += flow;
        }
        total += flow;
    }
    return total;
}

int main() {
    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> s1[i];
    for (int i = 0; i < n; ++i) cin >> s2[i];

    memset(head, -1, sizeof(head));
    edge_idx = 0;
    memset(id, -1, sizeof(id));
    cnt = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (s1[i][j] == 'Z') {
                xz = i; yz = j;
            } else if (check_inside(i, j)) {
                id[i][j] = ++cnt;
            }
        }
    source = 0; sink = 2 * cnt + 1;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (check_inside(i, j))
                for (int d = 0; d < 4; ++d) {
                    int x = i + directions[d][0], y = j + directions[d][1];
                    if (check_inside(x, y)) {
                        if (s2[x][y] != 0) {
                            add_edge(id[i][j] + cnt, sink, s2[x][y] - '0');
                        }
                        if (s1[i][j] == '0') continue;
                        add_edge(source, id[i][j], s1[i][j] - '0');
                        if (s2[x][y] != 0) {
                            add_edge(id[i][j], id[x][y] + cnt, 10);
                        }
                    }
                }
    cout << run_max_flow() << endl;
    return 0;
}
